mapper.select:
select a.id, b.name, d.warehouse_name, (select label from base_dict_data where type = 'GRAIN_VARIETY' and description = d.grain_variety) as grainVariety, (select label from base_dict_data where type = 'GRAIN_SOURCE_TYPE' and description = CAST(a.grain_source_type AS VARCHAR)) as grainSourceType, a.plan_weight as planWeight, a.completed_weight as completedWeight, a.state, a.start_time as startTime, a.end_time as endTime, c.name as addUser, a.add_time as addTime from warehouse_out_order a left join sts_customer b on a.customer_id =b.id left join base_user_info c on c.id = a.add_user left join sts_warehouse d on d.id = a.warehouse_id
and b.name like concat('%', #{name}, '%')
and d.grain_variety = #{grainVariety}
and a.warehouse_id = #{warehouseId}
order by a.add_time desc
